INSERT INTO `ins_categorias` (`codigo`, `descripcion`, `definicion`, `criterio_uso`, `grupo_operativo`, `created_at`, `updated_at`) VALUES
('bioestimulante', 'BIOESTIMULANTE', 'Productos que estimulan procesos fisiológicos de la planta, mejorando crecimiento, desarrollo o resistencia sin aportar nutrientes directos.', 'Se usa cuando el producto estimula raíces, brotamiento o defensas, pero no es fertilizante ni pesticida.', 'pesticida', '2026-04-08 22:23:37', '2026-04-08 22:23:37'),
('biologico', 'BIOLÓGICO', 'Productos basados en organismos vivos como bacterias, hongos o levaduras utilizados para control o mejora del suelo.', 'Se usa cuando el producto contiene microorganismos vivos.', 'pesticida', '2026-04-08 22:23:37', '2026-04-08 22:23:37'),
('coadyuvante', 'COADYUVANTE', 'Productos que mejoran la eficacia de aplicación o modifican condiciones del agua, suelo o mezcla sin acción directa sobre plagas o nutrición.', 'Se usa cuando el producto no nutre ni controla plagas, pero mejora la acción de otros productos o condiciones de aplicación.', 'pesticida', '2026-04-08 22:23:37', '2026-04-08 22:23:37'),
('combustible', 'COMBUSTIBLE', 'Sustancias utilizadas como fuente de energía para maquinaria agrícola.', 'Se usa para operación de equipos y no tiene relación directa con el cultivo.', 'combustible', '2025-12-19 06:32:20', '2026-04-08 22:23:37'),
('fertilizante', 'FERTILIZANTE', 'Productos que aportan nutrientes esenciales para el crecimiento y desarrollo de las plantas.', 'Se usa cuando el producto tiene como objetivo principal nutrir la planta o mejorar la fertilidad del suelo.', 'fertilizante', '2025-12-19 06:32:20', '2026-04-08 22:23:37'),
('pesticida', 'PESTICIDA', 'Productos destinados al control directo de plagas, enfermedades o malezas mediante acción química o biológica.', 'Se usa cuando el producto elimina o controla organismos dañinos como insectos, hongos, bacterias o malezas.', 'pesticida', '2026-04-08 22:23:11', '2026-04-08 22:23:11');
